:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #202d32;
  background: #eef2ea;
  --ink: #202d32;
  --muted: #64736e;
  --green: #28745f;
  --green-dark: #1e5949;
  --cream: #fbfcf8;
  --line: #d8e2d8;
  --gold: #e9b95d;
}

* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  padding: 24px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at top, #f8f8ef, #e7efe7 70%);
}
.card {
  width: min(100%, 460px);
  padding: clamp(22px, 6vw, 36px);
  border: 1px solid #dce5da;
  border-radius: 24px;
  background: var(--cream);
  box-shadow: 0 20px 60px #26433318, 0 3px 10px #2643330c;
}
header { text-align: center; }
.eyebrow {
  margin: 0 0 8px;
  color: var(--green);
  font-size: .8rem;
  font-weight: 750;
  letter-spacing: .12em;
  text-transform: uppercase;
}
h1 { margin: 0; font-size: clamp(2rem, 8vw, 2.5rem); letter-spacing: -.04em; }
.intro { margin: 8px 0 24px; color: var(--muted); line-height: 1.5; }
.play-area { padding: 16px; border-radius: 18px; background: #f0f4ed; }
.grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 7px;
  width: min(100%, 330px);
  aspect-ratio: 1;
  margin: 0 auto;
}
.cell {
  display: grid;
  place-items: center;
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fbfcf8;
}
.robot {
  position: relative;
  display: grid;
  place-items: center;
  width: 68%;
  height: 68%;
  border: 3px solid var(--green-dark);
  border-radius: 8px;
  background: var(--green);
  box-shadow: inset 0 -5px 0 #164b3d33, 0 2px 4px #173d3028;
  transition: transform 160ms ease;
}
.robot::before, .robot::after {
  content: "";
  position: absolute;
  top: 27%;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #fff6d8;
}
.robot::before { left: 22%; }
.robot::after { right: 22%; }
.robot-face { position: absolute; bottom: 16%; width: 28%; height: 3px; border-radius: 3px; background: #fff6d8; }
.robot[data-direction="right"] { transform: rotate(0deg); }
.robot[data-direction="down"] { transform: rotate(90deg); }
.robot[data-direction="left"] { transform: rotate(180deg); }
.robot[data-direction="up"] { transform: rotate(-90deg); }
.status { min-height: 24px; margin: 14px 0 0; text-align: center; color: #41534d; font-size: .94rem; font-weight: 600; }
.controls { display: grid; gap: 10px; margin-top: 20px; }
.turn-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.button {
  min-height: 48px;
  padding: 10px 14px;
  border: 1px solid #cbd8cd;
  border-radius: 12px;
  color: var(--ink);
  background: #fff;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  transition: transform 120ms ease, background 120ms ease, box-shadow 120ms ease;
}
.button:hover { background: #f1f6f0; box-shadow: 0 3px 8px #203d2815; }
.button:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
.button:active { transform: translateY(2px); box-shadow: none; }
.button-primary { border-color: var(--green); color: #fff; background: var(--green); }
.button-primary:hover { background: var(--green-dark); }
.button-reset { color: #54625b; background: transparent; }
.hint { margin: 16px 0 0; text-align: center; color: var(--muted); font-size: .88rem; }
@media (max-width: 380px) {
  body { padding: 14px 12px; }
  .card { padding: 22px 18px; }
  .grid { gap: 5px; }
  .cell { border-radius: 8px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; }
}

const grid = document.querySelector("#grid");
const status = document.querySelector("#status");
const directions = ["up", "right", "down", "left"];
const directionNames = { up: "up", right: "right", down: "down", left: "left" };
let row = 0;
let column = 0;
let direction = 1;

for (let r = 0; r < 5; r += 1) {
  for (let c = 0; c < 5; c += 1) {
    const cell = document.createElement("div");
    cell.className = "cell";
    cell.setAttribute("role", "gridcell");
    cell.dataset.row = r;
    cell.dataset.column = c;
    grid.append(cell);
  }
}

function render() {
  grid.querySelectorAll(".robot").forEach((robot) => robot.remove());
  const cell = grid.querySelector(`[data-row="${row}"][data-column="${column}"]`);
  const robot = document.createElement("span");
  robot.className = "robot";
  robot.dataset.direction = directions[direction];
  robot.setAttribute("role", "img");
  robot.setAttribute("aria-label", `Robot facing ${directionNames[directions[direction]]}`);
  const face = document.createElement("span");
  face.className = "robot-face";
  robot.append(face);
  cell.append(robot);
  status.textContent = `Position: row ${row + 1}, column ${column + 1}. Facing ${directions[direction]}.`;
}

function turn(amount) {
  direction = (direction + amount + 4) % 4;
  render();
}

function moveForward() {
  const deltas = [[-1, 0], [0, 1], [1, 0], [0, -1]];
  const nextRow = row + deltas[direction][0];
  const nextColumn = column + deltas[direction][1];
  if (nextRow >= 0 && nextRow < 5 && nextColumn >= 0 && nextColumn < 5) {
    row = nextRow;
    column = nextColumn;
  }
  render();
}

function reset() {
  row = 0;
  column = 0;
  direction = 1;
  render();
}

document.querySelector("#forward").addEventListener("click", moveForward);
document.querySelector("#left").addEventListener("click", () => turn(-1));
document.querySelector("#right").addEventListener("click", () => turn(1));
document.querySelector("#reset").addEventListener("click", reset);

document.addEventListener("keydown", (event) => {
  if (event.altKey || event.ctrlKey || event.metaKey) return;
  if (event.key === "ArrowRight") { event.preventDefault(); moveForward(); }
  if (event.key === "ArrowUp") { event.preventDefault(); turn(-1); }
  if (event.key === "ArrowDown") { event.preventDefault(); turn(1); }
});

render();
